const feeds = [
  'https://news.google.com/rss/search?q=Revit+OR+BIM+OR+Navisworks+architecture+when:2d&hl=en-US&gl=US&ceid=US:en',
  'https://news.google.com/rss/search?q=SketchUp+OR+Lumion+OR+Enscape+OR+Twinmotion+when:2d&hl=en-US&gl=US&ceid=US:en',
  'https://news.google.com/rss/search?q=%22building+permit%22+OR+%22construction+documents%22+OR+ADU+when:2d&hl=en-US&gl=US&ceid=US:en',
  'https://news.google.com/rss/search?q=AI+architecture+BIM+standards+when:2d&hl=en-US&gl=US&ceid=US:en',
  'https://www.reddit.com/r/Revit/.rss',
  'https://www.reddit.com/r/architecture/.rss',
  'https://www.archdaily.com/rss/'
];
return feeds.map(url => ({ json: { url } }));

// Handles both RSS 2.0 (<item>) and Atom (<entry>, used by Reddit) without external XML libs.
function stripCdataAndTags(s) {
  if (!s) return '';
  return s.replace(/<!\[CDATA\[/g, '').replace(/\]\]>/g, '').replace(/<[^>]+>/g, '').trim();
}
function extractTag(tag, block) {
  const re = new RegExp('<' + tag + '[^>]*>([\\s\\S]*?)<\\/' + tag + '>', 'i');
  const m = block.match(re);
  return m ? stripCdataAndTags(m[1]) : '';
}
function extractLink(block) {
  // Atom-style self-closing: <link rel="alternate" href="..."/>
  const hrefMatch = block.match(/<link[^>]*href="([^"]+)"/i);
  if (hrefMatch) return hrefMatch[1];
  return extractTag('link', block);
}

const out = [];
for (const item of $input.all()) {
  const raw = item.json.data ?? item.json.body ?? (typeof item.json === 'string' ? item.json : null);
  if (!raw || typeof raw !== 'string') continue; // skip failed/blocked feed fetches

  const blocks = raw.match(/<item[\s\S]*?<\/item>|<entry[\s\S]*?<\/entry>/gi) || [];
  for (const block of blocks) {
    const title = extractTag('title', block);
    if (!title) continue;
    const link = extractLink(block);
    const pubDate = extractTag('pubDate', block) || extractTag('updated', block) || extractTag('published', block);
    const summary = (extractTag('description', block) || extractTag('summary', block) || extractTag('content', block)).slice(0, 500);
    out.push({ json: { title, link, pubDate, summary } });
  }
}
return out;

const cutoff = Date.now() - 48*60*60*1000;
const out = [];
for (const item of $input.all()) {
  const d = item.json.pubDate || item.json.isoDate || item.json.date;
  const t = d ? new Date(d).getTime() : 0;
  if (t >= cutoff) {
    out.push({
      json: {
        title: item.json.title || '',
        summary: (item.json.content || item.json.contentSnippet || item.json.summary || '').toString().slice(0, 500),
        link: item.json.link || '',
        pubDate: d
      }
    });
  }
}
return out;

const keywords = ['Revit','BIM','SketchUp','Lumion','Navisworks','Bluebeam','AutoCAD','Enscape','Twinmotion','ADU','permit','construction documents','AI architecture'];
const items = $input.all().map(i => i.json);
const counts = {};
const examples = {};
for (const kw of keywords) counts[kw] = 0;
for (const it of items) {
  const text = (it.title + ' ' + it.summary).toLowerCase();
  for (const kw of keywords) {
    if (text.includes(kw.toLowerCase())) {
      counts[kw]++;
      if (!examples[kw] || new Date(it.pubDate) > new Date(examples[kw].pubDate)) {
        examples[kw] = it;
      }
    }
  }
}
let topKw = null, topCount = 0;
for (const kw of keywords) {
  if (counts[kw] > topCount) { topCount = counts[kw]; topKw = kw; }
}
if (!topKw) {
  // fallback: no keyword matches, use most recent item overall
  const sorted = items.sort((a,b) => new Date(b.pubDate) - new Date(a.pubDate));
  return [{ json: { keyword: 'AEC industry', count: 0, article: sorted[0] || { title: 'General AEC trends', summary: '', link: '' } } }];
}
return [{ json: { keyword: topKw, count: topCount, article: examples[topKw] } }];

const raw = $json.choices?.[0]?.message?.content || '';
const cleaned = raw.replace(/```json|```/g, '').trim();
let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (e) {
  throw new Error('LLM did not return valid JSON: ' + cleaned.slice(0,300));
}
if (!parsed.post_text || !parsed.image_prompt) {
  throw new Error('LLM JSON missing required fields');
}
return [{ json: {
  post_text: parsed.post_text,
  hashtags: Array.isArray(parsed.hashtags) ? parsed.hashtags.join(' ') : (parsed.hashtags || ''),
  image_prompt: parsed.image_prompt,
  trending_topic: $('Rank Trending Topic').first().json.keyword
} }];
